<?php
if (!defined('ROUTER_LOADED')) { http_response_code(403); exit('Accès direct interdit.'); }
if (!userCan($user, 'caisse.view')) { http_response_code(403); echo '<div class="rounded-md border border-red-200 bg-red-50 p-4 text-red-700">Accès refusé.</div>'; return; }
require_once __DIR__ . '/../../api/database.php'; require_once __DIR__ . '/_finance.php';
$db=Database::getInstance(); $role=$user['role_system'];
$from=(string)($_GET['du']??date('Y-m-01')); $to=(string)($_GET['au']??date('Y-m-d')); $search=trim((string)($_GET['q']??'')); $type=(string)($_GET['type']??'');
if(!financeValidDate($from))$from=date('Y-m-01'); if(!financeValidDate($to))$to=date('Y-m-d'); if($from>$to)[$from,$to]=[$to,$from];
$validTypes=['Vente comptoir','Entrée manuelle','Sortie caisse']; if(!in_array($type,$validTypes,true))$type='';
$union="SELECT operation_date, operation_type, reference, description, amount, payment_info FROM (
    SELECT date AS operation_date, 'Vente comptoir' AS operation_type, invoice_number AS reference, client_name AS description, netcash AS amount, payment_method AS payment_info FROM sales WHERE status = 'Active' AND origin = 'Vente comptoir' AND payment_method = 'Espèces' AND netcash > 0
    UNION ALL SELECT date_created AS operation_date, 'Entrée manuelle' AS operation_type, COALESCE(reference,'') AS reference, trans_motive AS description, amount AS amount, 'Encaissement libre' AS payment_info FROM cash_in WHERE NOT EXISTS (SELECT 1 FROM sales WHERE sales.invoice_number = cash_in.reference AND sales.origin = 'Vente comptoir' AND sales.payment_method = 'Espèces')
    UNION ALL SELECT created_at AS operation_date, 'Sortie caisse' AS operation_type, CAST(id AS CHAR) AS reference, COALESCE(reason,cashout_type) AS description, amount AS amount, cashout_type AS payment_info FROM cash_out
) AS finance_ops";
$conditions=['operation_date BETWEEN ? AND ?']; $params=[$from,$to];
if($type!==''){$conditions[]='operation_type = ?';$params[]=$type;}
if($search!==''){$conditions[]='(reference LIKE ? OR description LIKE ? OR payment_info LIKE ?)';$p='%'.$search.'%';array_push($params,$p,$p,$p);}
$where=' WHERE '.implode(' AND ',$conditions);
$total=(int)$db->fetchColumn("SELECT COUNT(*) FROM ($union) AS all_ops$where",$params);
$totals=$db->fetch("SELECT COALESCE(SUM(CASE WHEN operation_type IN ('Vente comptoir','Entrée manuelle') THEN amount ELSE 0 END),0) AS total_in, COALESCE(SUM(CASE WHEN operation_type = 'Sortie caisse' THEN amount ELSE 0 END),0) AS total_out FROM ($union) AS all_ops WHERE operation_date BETWEEN ? AND ?",[$from,$to]);
$page=max(1,(int)($_GET['page']??1));$perPage=25;$pages=max(1,(int)ceil($total/$perPage));$page=min($page,$pages);$offset=($page-1)*$perPage;
$operations=$db->fetchAll("SELECT * FROM ($union) AS all_ops$where ORDER BY operation_date DESC, reference DESC LIMIT $perPage OFFSET $offset",$params);
$flash=$_SESSION['flash_message']??null;unset($_SESSION['flash_message']);
$pageUrl=static fn(int $target):string=>app_route_url('caisse/transactions',$role).'?'.http_build_query(['du'=>$from,'au'=>$to,'q'=>$search,'type'=>$type,'page'=>$target]);
?>
<section class="space-y-5"><header class="flex flex-col gap-3 sm:flex-row sm:items-end sm:justify-between"><div><p class="text-sm font-semibold text-amber-800">Caisse</p><h1 class="mt-1 text-2xl font-bold text-slate-900">Transactions caisse</h1><p class="mt-1 text-sm text-slate-600"><?=number_format($total,0,',',' ')?> opération(s) sur la période</p></div><a href="<?=financeEscape(app_route_url('caisse/rapports'))?>" class="rounded-md border border-slate-300 bg-white px-4 py-2.5 text-sm font-semibold text-slate-700">Rapports financiers</a></header>
<?php if($flash):?><div role="status" class="rounded-md border border-green-200 bg-green-50 px-4 py-3 text-sm text-green-800"><?=financeEscape($flash['text']??'')?></div><?php endif;?>
<div class="grid gap-3 sm:grid-cols-2"><article class="rounded-md border border-slate-200 bg-white p-4"><p class="text-sm text-slate-500">Entrées affichées</p><p class="mt-1 text-xl font-bold text-green-800"><?=number_format((float)$totals['total_in'],0,',',' ')?> FBu</p></article><article class="rounded-md border border-slate-200 bg-white p-4"><p class="text-sm text-slate-500">Sorties caisse affichées</p><p class="mt-1 text-xl font-bold text-rose-700"><?=number_format((float)$totals['total_out'],0,',',' ')?> FBu</p></article></div>
<form method="get" action="<?=financeEscape(app_url('router.php'))?>" class="grid gap-3 rounded-md border border-slate-200 bg-white p-4 sm:grid-cols-2 xl:grid-cols-[1fr_1fr_1fr_1.4fr_auto_auto] xl:items-end"><input type="hidden" name="route" value="<?=financeEscape($role.'/caisse/transactions')?>"><label class="space-y-1 text-sm font-medium">Du<input type="date" name="du" value="<?=financeEscape($from)?>" class="w-full rounded-md border border-slate-300 px-3 py-2 font-normal"></label><label class="space-y-1 text-sm font-medium">Au<input type="date" name="au" value="<?=financeEscape($to)?>" class="w-full rounded-md border border-slate-300 px-3 py-2 font-normal"></label><label class="space-y-1 text-sm font-medium">Type<select name="type" class="w-full rounded-md border border-slate-300 bg-white px-3 py-2 font-normal"><option value="">Tous</option><?php foreach($validTypes as $option):?><option value="<?=financeEscape($option)?>" <?=$type===$option?'selected':''?>><?=financeEscape($option)?></option><?php endforeach;?></select></label><label class="space-y-1 text-sm font-medium">Recherche<input name="q" value="<?=financeEscape($search)?>" placeholder="Référence, libellé, paiement" class="w-full rounded-md border border-slate-300 px-3 py-2 font-normal"></label><button class="rounded-md border border-slate-300 px-4 py-2 text-sm font-medium">Filtrer</button><?php if($search!==''||$type!==''||$from!==date('Y-m-01')||$to!==date('Y-m-d')):?><a href="<?=financeEscape(app_route_url('caisse/transactions'))?>" class="px-3 py-2 text-sm text-slate-600">Effacer</a><?php endif;?></form>
<div class="overflow-x-auto rounded-md border border-slate-200 bg-white"><table class="min-w-full divide-y text-sm"><thead class="bg-slate-50 text-left text-xs uppercase text-slate-500"><tr><th class="px-4 py-3">Date</th><th class="px-4 py-3">Type</th><th class="px-4 py-3">Référence</th><th class="px-4 py-3">Libellé</th><th class="px-4 py-3">Mode / détail</th><th class="px-4 py-3 text-right">Montant</th></tr></thead><tbody class="divide-y divide-slate-100"><?php if(!$operations):?><tr><td colspan="6" class="px-4 py-12 text-center text-slate-500">Aucune transaction sur cette période.</td></tr><?php else:foreach($operations as $operation):$out=$operation['operation_type']==='Sortie caisse';?><tr><td class="whitespace-nowrap px-4 py-3 text-slate-600"><?=financeEscape(date('d/m/Y',strtotime($operation['operation_date'])))?></td><td class="px-4 py-3"><span class="rounded-full px-2 py-1 text-xs <?=$out?'bg-rose-100 text-rose-800':'bg-green-100 text-green-800'?>"><?=financeEscape($operation['operation_type'])?></span></td><td class="px-4 py-3 font-mono text-xs"><?=financeEscape($operation['reference']?:'—')?></td><td class="px-4 py-3 font-medium text-slate-900"><?=financeEscape($operation['description']?:'—')?></td><td class="px-4 py-3 text-slate-600"><?=financeEscape($operation['payment_info']?:'—')?></td><td class="whitespace-nowrap px-4 py-3 text-right font-semibold <?=$out?'text-rose-700':'text-slate-900'?>"><?=$out?'−':'+'?><?=number_format((float)$operation['amount'],0,',',' ')?> FBu</td></tr><?php endforeach;endif;?></tbody></table></div>
<?php if($pages>1):?><nav class="flex items-center justify-between"><span class="text-sm text-slate-600">Page <?=$page?> sur <?=$pages?></span><div class="flex gap-2"><?php if($page>1):?><a href="<?=financeEscape($pageUrl($page-1))?>" class="rounded border px-3 py-2 text-sm">Précédent</a><?php endif;?><?php if($page<$pages):?><a href="<?=financeEscape($pageUrl($page+1))?>" class="rounded border px-3 py-2 text-sm">Suivant</a><?php endif;?></div></nav><?php endif;?></section>